mapper.select:
select pre.P_Name as pName, con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conAmount,
mn.* from Inv_Adjustment mn left join Pre_Project pre on mn.P_ID= pre.P_ID left join Con_Contract con on con.Con_Id= mn.Con_Id
${params.authSql}
and mn.Te_Id = #{params.teId}
and pre.P_Name like concat('%',#{params.pName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time DESC
